head.script:
scwin.trigger1_onclick = function(e) {
    $w.dynamicCreate("secret1", "secret", {}, group1);
    //alert ("secret 생성");
    log = "secret 생성";
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 2. 브라우저에서 dynamic_create 버튼을 클릭한다.
    //2. Click the dynamic_create button in the browser.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. secret 생성 팝업이 생성되면서 동적으로 secret컴포넌트가 생성된다. (생성여부는 로그에서 확인)
    //2. Create Secret Generate a secret component dynamically as popup is created. (Whether it is created or not)
    WebSquare.wUnit.addCommand("assert", "log", "secret 생성");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = "";
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 01-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
